def is_sum_of_two_squares_exact(n):
    if n < _sage_const_0 : return False
    if n == _sage_const_0  or n == _sage_const_1 : return True
    factors = factor(n)
    for p, exp in factors:
        if p % _sage_const_4  == _sage_const_3  and exp % _sage_const_2  != _sage_const_0 :
            return False
    return True

